let tenths = 0;
let timer = null;
const watch = document.querySelector("#watch");

function show() {
  watch.textContent = (tenths / 10).toFixed(1);
}

function stop() {
  clearInterval(timer);
  timer = null;
}

// Başlat, Durdur ve Sıfırla düğmelerini dinle
document.querySelector("#start").addEventListener("click", () => {
  if (timer !== null) return; // zaten çalışıyor
  timer = setInterval(() => {
    tenths++;
    show();
  }, 100);
});
document.querySelector("#stop").addEventListener("click", stop);
document.querySelector("#reset").addEventListener("click", () => {
  stop();
  tenths = 0;
  show();
});

check.js:
click("#start");
click("#start");
await sleep(450);
assert(tenths >= 3 && tenths <= 6, "450 ms sonra tenths yaklaşık 4 olmalı. İki kez Başlat'a basınca sayaçlar üst üste binmemeli!");
assert($("#watch").textContent === (tenths / 10).toFixed(1), "#watch tenths'i '0.4' biçiminde göstermeli.");
click("#stop");
const stopped = tenths;
await sleep(200);
assert(tenths === stopped, "Durdur'a basınca sayaç durmalı.");
click("#start");
await sleep(250);
assert(tenths > stopped, "Durdurduktan sonra Başlat yeniden çalışmalı (timer = null yapmayı unutma).");
click("#reset");
assert(tenths === 0 && $("#watch").textContent === "0.0", "Sıfırla tenths'i 0 yapmalı ve '0.0' göstermeli.");
await sleep(200);
assert(tenths === 0, "Sıfırla sayacı da durdurmalı.");

