tick();
assert(secondsLeft === 1499 && $("#focus-time").textContent === "24:59", "tick() bir saniye azaltmalı ve render() ile '24:59' göstermeli.");
secondsLeft = 2;
tick();
tick();
tick();
assert(secondsLeft === 0 && $("#focus-time").textContent === "00:00", "Süre 0'ın altına inmemeli.");
assert($("#focus-msg").textContent === "Mola zamanı!", "Süre bitince #focus-msg 'Mola zamanı!' olmalı.");
secondsLeft = 100;
click("#focus-start");
click("#focus-start");
await sleep(450);
assert(secondsLeft >= 94 && secondsLeft <= 98, "Başlat'tan sonra her TICK_MS'de 1 azalmalı; iki kez Başlat'a basınca sayaç iki kat hızlanmamalı.");
click("#focus-pause");
const paused = secondsLeft;
await sleep(250);
assert(secondsLeft === paused, "Duraklat'a basınca sayaç durmalı.");

