project_task.solution:
const question = { text: "Ay, hangi gezegenin uydusudur?", options: ["Mars", "Dünya", "Jüpiter"], correct: 1 };
const buttons = document.querySelectorAll(".option");
const feedback = document.querySelector("#feedback");
let score = 0;
let answered = false;
const TICK_MS = 100; // gerçekte 1000 (1 saniye)
let timeLeft = 10;
let timer = null;
const timeEl = document.querySelector("#time");

function answer(index) {
  if (answered) return;
  answered = true;
  // sayacı durdur
  clearInterval(timer);
  if (index === question.correct) {
    score += 10;
    document.querySelector("#score").textContent = score;
    feedback.textContent = "Doğru!";
  } else {
    feedback.textContent = `Yanlış! Doğru cevap: ${question.options[question.correct]}`;
  }
}
buttons.forEach((btn, i) => btn.addEventListener("click", () => answer(i)));

function tick() {
  // süreyi azalt; 0 olunca durdur, "Süre doldu!", düğmeleri kapat
  if (timeLeft > 0) timeLeft--;
  timeEl.textContent = timeLeft;
  if (timeLeft === 0) {
    clearInterval(timer);
    answered = true;
    feedback.textContent = "Süre doldu!";
    buttons.forEach((btn) => (btn.disabled = true));
  }
}

function startQuestion() {
  // her şeyi sıfırla ve sayacı başlat
  clearInterval(timer);
  timeLeft = 10;
  answered = false;
  feedback.textContent = "";
  timeEl.textContent = timeLeft;
  buttons.forEach((btn) => (btn.disabled = false));
  timer = setInterval(tick, TICK_MS);
}

document.querySelector("#player-form").addEventListener("submit", (e) => {
  e.preventDefault();
  startQuestion();
});

check.js:
const opts = $$(".option");
tick();
assert(timeLeft === 9 && $("#time").textContent === "9", "tick() süreyi 1 azaltmalı ve #time'a yazmalı.");
timeLeft = 1;
tick();
assert(timeLeft === 0 && $("#feedback").textContent === "Süre doldu!", "Süre bitince #feedback 'Süre doldu!' olmalı.");
assert(opts.every((b) => b.disabled), "Süre bitince seçenek düğmeleri kapanmalı (disabled).");
tick();
assert(timeLeft === 0, "Süre 0'ın altına inmemeli.");
answer(1);
assert(score === 0, "Süre dolduktan sonra verilen cevap sayılmamalı (answered = true).");
startQuestion();
startQuestion();
assert(timeLeft === 10 && $("#feedback").textContent === "" && opts.every((b) => !b.disabled), "startQuestion() süreyi 10 yapmalı, #feedback'i boşaltmalı ve düğmeleri açmalı.");
await sleep(350);
assert(timeLeft >= 6 && timeLeft <= 8, "Sayaç her TICK_MS'de 1 azalmalı; iki kez başlatınca sayaçlar üst üste binmemeli.");
answer(1);
assert(score === 10, "Yeni soruda doğru cevap puan kazandırmalı.");
const left = timeLeft;
await sleep(250);
assert(timeLeft === left, "Cevap verilince sayaç durmalı (answer içinde clearInterval).");
